static float rf(const OrpheusConfig* c,const char* id,float fallback){for(uint32_t i=0;i<c->param_count;++i)if(c->param_ids[i]&&strcmp(c->param_ids[i],id)==0){if(c->param_values[i].type==ORPHEUS_VALUE_FLOAT)return c->param_values[i].value.f32;if(c->param_values[i].type==ORPHEUS_VALUE_INT)return(float)c->param_values[i].value.i32;}return fallback;}
static int32_t ri(const OrpheusConfig* c,const char* id,int32_t fallback){for(uint32_t i=0;i<c->param_count;++i)if(c->param_ids[i]&&strcmp(c->param_ids[i],id)==0){if(c->param_values[i].type==ORPHEUS_VALUE_INT)return c->param_values[i].value.i32;if(c->param_values[i].type==ORPHEUS_VALUE_FLOAT)return(int32_t)c->param_values[i].value.f32;if(c->param_values[i].type==ORPHEUS_VALUE_BOOL)return c->param_values[i].value.b?1:0;}return fallback;}
static const char* rs(const OrpheusConfig* c,const char* id,const char* fallback){for(uint32_t i=0;i<c->param_count;++i)if(c->param_ids[i]&&strcmp(c->param_ids[i],id)==0&&c->param_values[i].type==ORPHEUS_VALUE_STRING)return c->param_values[i].value.str?c->param_values[i].value.str:fallback;return fallback;}
static uint32_t parse(const char* text,float* out){uint32_t n=0;const char* p=text;while(p&&*p&&n<INDEXED_GAIN_MAX_TABLE){char* end=NULL;out[n++]=strtof(p,&end);if(end==p)break;p=end;while(*p==','||*p==' '||*p=='\t')++p;}return n;}
static float target(const IndexedGainState* s){float index=fminf(255.0f,fmaxf(0.0f,s->gain_index));float db=s->table_db[0];if(index<=s->table_idx[0])db=s->table_db[0];else for(uint32_t i=1;i<s->table_size;++i){if(index<=s->table_idx[i]){float d=s->table_idx[i]-s->table_idx[i-1];float f=d!=0?(index-s->table_idx[i-1])/d:1;db=s->table_db[i-1]+f*(s->table_db[i]-s->table_db[i-1]);break;}}db+=fminf(0.0f,fmaxf(-10.0f,s->gain_offset_db));db=fminf(s->max_gain_db,db);return powf(10.0f,db/20.0f);}
static void ramp(IndexedGainState* s){s->target_gain=fmaxf(target(s),INDEXED_GAIN_SILENT);float cur=fmaxf(s->current_gain,INDEXED_GAIN_SILENT);float diff=fabsf(20*log10f(s->target_gain/cur));if(diff<.01f||s->ramp_ms<=0){s->current_gain=s->target_gain;s->frame_count=0;s->ramp_coeff=1;return;}float ms=s->ramp_ms;if(s->ramp_db_per_s>0){float rate=fminf(50000,fmaxf(5,s->ramp_db_per_s));ms=diff/rate*1000;}ms=fminf(3000,fmaxf(1,ms));s->frame_count=(uint32_t)ceilf(ms/(1000*(float)s->block_size/s->sample_rate));if(s->frame_count<1)s->frame_count=1;s->ramp_coeff=expf(logf(s->target_gain/cur)/((float)s->block_size*s->frame_count));}
