static const OrpheusComponentDescriptor* gd(void){return&desc;}static int create(void**s,const OrpheusConfig*c){if(c&&c->state_block){*s=c->state_block;return 0;}*s=calloc(1,sizeof(IndexedGainState));return*s?0:ORPHEUS_ERR_OUT_OF_MEMORY;}static int destroy(void*s){(void)s;return 0;}
static int prepare(void*o,const OrpheusConfig*c){IndexedGainState*s=o;s->channels=(uint32_t)ri(c,"channels",2);if(s->channels>64)s->channels=64;s->block_size=c->block_size?c->block_size:32;s->sample_rate=c->sample_rate?c->sample_rate:48000;s->gain_index=rf(c,"gain_index",255);s->gain_offset_db=rf(c,"gain_offset_db",0);s->max_gain_db=rf(c,"max_gain_db",0);s->ramp_ms=rf(c,"ramp_ms",100);s->ramp_db_per_s=rf(c,"ramp_db_per_s",0);s->freeze=ri(c,"freeze",0)!=0;uint32_t ni=parse(rs(c,"table_idx","0,255"),s->table_idx),nd=parse(rs(c,"table_db","-96,0"),s->table_db);s->table_size=ni<nd?ni:nd;if(!s->table_size)s->table_size=1;s->current_gain=ri(c,"apply_index_on_prepare",1)?target(s):rf(c,"initial_gain",1);s->target_gain=s->current_gain;s->ramp_coeff=1;s->frame_count=0;return 0;}static int reset(void*o){IndexedGainState*s=o;s->frame_count=0;s->ramp_coeff=1;return 0;}
static int process(void*o,const OrpheusProcessContext*c){IndexedGainState*s=o;const OrpheusBuffer*i=c->inputs[0];OrpheusBuffer*out=c->outputs[0];if(!i||!out)return ORPHEUS_ERR_INVALID_ARG;const float*x=i->data;float*y=out->data;for(uint32_t n=0;n<c->frame_count;++n){if(!s->freeze&&s->frame_count)s->current_gain*=s->ramp_coeff;for(uint32_t ch=0;ch<s->channels;++ch)y[n*s->channels+ch]=x[n*s->channels+ch]*s->current_gain;}if(!s->freeze&&s->frame_count&&--s->frame_count==0){s->current_gain=s->target_gain;s->ramp_coeff=1;}out->frame_count=c->frame_count;return 0;}
static int setp(void*o,const char*id,const OrpheusValue*v){IndexedGainState*s=o;if(strcmp(id,"gain_index")==0){s->gain_index=v->type==ORPHEUS_VALUE_FLOAT?v->value.f32:(float)v->value.i32;ramp(s);return 0;}if(strcmp(id,"gain_offset_db")==0){s->gain_offset_db=v->type==ORPHEUS_VALUE_FLOAT?v->value.f32:(float)v->value.i32;ramp(s);return 0;}if(strcmp(id,"ramp_ms")==0){s->ramp_ms=v->type==ORPHEUS_VALUE_FLOAT?v->value.f32:(float)v->value.i32;return 0;}if(strcmp(id,"ramp_db_per_s")==0){s->ramp_db_per_s=v->type==ORPHEUS_VALUE_FLOAT?v->value.f32:(float)v->value.i32;return 0;}if(strcmp(id,"freeze")==0){s->freeze=v->type==ORPHEUS_VALUE_BOOL?v->value.b:v->value.i32!=0;return 0;}return ORPHEUS_ERR_NOT_FOUND;}static int getp(void*o,const char*id,OrpheusValue*v){IndexedGainState*s=o;if(strcmp(id,"gain_index")==0){v->type=ORPHEUS_VALUE_FLOAT;v->value.f32=s->gain_index;return 0;}if(strcmp(id,"current_gain")==0){v->type=ORPHEUS_VALUE_FLOAT;v->value.f32=s->current_gain;return 0;}return ORPHEUS_ERR_NOT_FOUND;}static int slots(void*o,const OrpheusRegistry*r){(void)o;(void)r;return 0;}
